import math

def relu(x):    return max(0.0, x)
def sigmoid(x): return 1 / (1 + math.exp(-x))
def tanh(x):    return math.tanh(x)

vals = [-2.0, -0.5, 0.5, 2.0]
for v in vals:
    print(f"x={v:5.1f}  relu={relu(v):5.2f}  sigmoid={sigmoid(v):5.2f}  tanh={tanh(v):5.2f}")

# Architectures in shape notation
architectures = {
    "MLP (tabular)":       "input → dense(256) → relu → dense(10)",
    "CNN (images)":         "input → conv → relu → pool → dense → softmax",
    "Transformer (text)":   "input → attention → feedforward → attention → ...",
}

for name, shape in architectures.items():
    print(f"{name}: {shape}")
